const response = $input.first().json;
const records = response.records || [];
const now = Date.now();
const DAY = 86400000;

const healthy = [];
const warning = [];
const critical = [];

for (const rec of records) {
  const f = rec.fields;
  const name = f.Creator || 'Unknown';

  const capturedAt = f.Refresh_Token_Captured_At 
    ? new Date(f.Refresh_Token_Captured_At).getTime() 
    : null;
  const lastRefreshed = f.Last_Refreshed 
    ? new Date(f.Last_Refreshed).getTime() 
    : null;

  const daysSinceCapture = capturedAt ? Math.round((now - capturedAt) / DAY) : null;
  const daysSinceRefresh = lastRefreshed ? Math.round(((now - lastRefreshed) / DAY) * 10) / 10 : null;
  const failures = f.Consecutive_Failures || 0;
  const status = f.Status || 'unknown';

  const entry = {
    name,
    daysSinceCapture: daysSinceCapture !== null ? daysSinceCapture : 'unknown',
    daysSinceRefresh: daysSinceRefresh !== null ? daysSinceRefresh : 'unknown',
    failures,
    status,
    error: f.Error_Message || ''
  };

  // Critical: token very old, has failures, or in error state
  if (
    (daysSinceCapture !== null && daysSinceCapture > 80) ||
    failures > 0 ||
    status === 'error' ||
    status === 'expired'
  ) {
    critical.push(entry);
  }
  // Warning: token aging or hasn't refreshed recently
  else if (
    (daysSinceCapture !== null && daysSinceCapture > 60) ||
    (daysSinceRefresh !== null && daysSinceRefresh > 1)
  ) {
    warning.push(entry);
  }
  // Healthy
  else {
    healthy.push(entry);
  }
}

const hasIssues = warning.length > 0 || critical.length > 0;
const total = records.length;

// Build email body
let emailBody = `LTK Token Health Report\n`;
emailBody += `========================\n\n`;
emailBody += `Summary: ${total} creators tracked\n`;
emailBody += `  Healthy:  ${healthy.length}\n`;
emailBody += `  Warning:  ${warning.length}\n`;
emailBody += `  Critical: ${critical.length}\n\n`;

if (critical.length > 0) {
  emailBody += `CRITICAL (action needed):\n`;
  for (const c of critical) {
    emailBody += `  - ${c.name}: ${c.failures} failures, token ${c.daysSinceCapture} days old, status=${c.status}`;
    if (c.error) emailBody += `, error: ${c.error.substring(0, 100)}`;
    emailBody += `\n`;
  }
  emailBody += `\n`;
}

if (warning.length > 0) {
  emailBody += `WARNING (monitor):\n`;
  for (const w of warning) {
    emailBody += `  - ${w.name}: token ${w.daysSinceCapture} days old, last refreshed ${w.daysSinceRefresh} days ago\n`;
  }
  emailBody += `\n`;
}

if (healthy.length > 0) {
  emailBody += `HEALTHY:\n`;
  for (const h of healthy) {
    emailBody += `  - ${h.name}: OK\n`;
  }
  emailBody += `\n`;
}

emailBody += `---\n`;
emailBody += `For critical creators, re-capture their refresh token from browser.\n`;
emailBody += `Open https://creator.shopltk.com, log in, DevTools > Application > Local Storage > @@auth0spajs@@ > refresh_token\n`;

return [{
  json: {
    hasIssues,
    total,
    healthyCount: healthy.length,
    warningCount: warning.length,
    criticalCount: critical.length,
    emailSubject: `LTK Token Health: ${critical.length} critical, ${warning.length} warning, ${healthy.length} healthy`,
    emailBody
  }
}];
